import {ASTRAL_COST,ASTRAL_SLOTS,ASTRAL_RELICS} from './astral.js';
import {glyph} from './ui-art.js';
export function astralMarkup(s){const a=s.astral,remaining=ASTRAL_RELICS.length-a.owned.length;return `<section class="astral-header"><div><h2>ECOS DAS ESTRELAS</h2></div><strong>★ ${s.stars}</strong></section><div class="astral-layout"><section class="astral-altar"><div class="astral-sigil">✦</div><h3>${a.offer.length?'ESCOLHA UM ECO':remaining?'NOVO ECO':'COLEÇÃO COMPLETA'}</h3><p>${a.offer.length?'PERMANENTE':'3 OPÇÕES · ESCOLHA 1'}</p>${!a.offer.length?`<button class="primary" id="rollAstral" ${s.stars<ASTRAL_COST||!remaining?'disabled':''}>INVOCAR · ★ ${ASTRAL_COST}</button><span class="astral-rule">${remaining} ECOS A DESCOBRIR</span>`:''}</section><section><div class="astral-slots"><b>${a.equipped.length}/${ASTRAL_SLOTS} ATIVOS</b>${Array.from({length:ASTRAL_SLOTS},(_,i)=>{const r=ASTRAL_RELICS.find(r=>r.id===a.equipped[i]);return `<span title="${r?.text||'Espaço livre'}">${r?glyph(r.icon):'◇'}<small>${r?.name||'LIVRE'}</small></span>`;}).join('')}</div>${a.offer.length?`<div class="astral-offer">${a.offer.map(id=>{const r=ASTRAL_RELICS.find(r=>r.id===id);return `<article>${glyph(r.icon)}<h3>${r.name}</h3><p>${r.text}</p><button class="primary" data-choose-astral="${id}">ESCOLHER</button></article>`;}).join('')}</div>`:`<details class="quiet-details astral-intro"><summary>COMO FUNCIONA</summary><p>Até três ecos ativos. Troque na vila.</p><p>O sorteio fica salvo e nunca repete um eco da coleção.</p></details>`}</section></div><div class="astral-collection-heading"><h3>COLEÇÃO · ${a.owned.length}/30</h3><span>TROQUE NA VILA</span></div><div class="astral-collection">${ASTRAL_RELICS.map(r=>{const owned=a.owned.includes(r.id),active=a.equipped.includes(r.id);return `<button class="${owned?'owned':''} ${active?'active':''}" data-equip-astral="${r.id}" aria-pressed="${active}" ${!owned||!active&&a.equipped.length>=3?'disabled':''}>${glyph(r.icon)}<span><b>${r.name}</b><small>${r.text}</small></span><em>${active?'✓':owned?'EQUIPAR':'◇'}</em></button>`;}).join('')}</div>`;}
